from qlib import Q
C='wedding-fashion-trend'
Q(C,'basic',"TPO 메이크업에서 TPO 가 뜻하는 것은?","시간(Time)·장소(Place)·상황(Occasion)",[("유형(Type)·비율(Proportion)·윤곽(Outline)","TPO 의 뜻이 아닙니다."),("톤(Tone)·피부(Pore)·오일(Oil)","TPO 의 뜻이 아닙니다."),("트렌드(Trend)·개성(Personality)·직업(Occupation)","TPO 의 뜻이 아닙니다.")],"TPO = Time·Place·Occasion","**TPO** 는 **시간(Time), 장소(Place), 상황(Occasion)**의 머리글자입니다. 같은 사람이라도 낮의 면접과 밤의 파티는 메이크업이 달라야 한다는 뜻입니다.",5,["TPO 메이크업"])
Q(C,'basic',"신부 본식 메이크업의 기본 방향으로 가장 알맞은 것은?","깨끗하고 화사한 피부 표현에 드레스와 어울리는 단정한 색조를 쓴다",[("진하고 어두운 스모키 메이크업을 기본으로 한다","본식에는 맑고 단정한 이미지가 기본입니다."),("반짝이는 펄을 얼굴 전체에 두껍게 바른다","사진에 번들거려 보입니다."),("피부 표현을 하지 않고 립만 진하게 바른다","균형이 맞지 않습니다.")],"신부 본식 = 깨끗한 피부·화사함·단정함","신부 본식 메이크업은 **깨끗하고 화사한 피부 표현**을 기본으로 드레스·헤어·예식장 조명과 어울리는 **단정한 색조**를 씁니다. 오랜 시간 유지되도록 베이스를 꼼꼼히 밀착시킵니다.",4,["웨딩 메이크업"])
Q(C,'intermediate',"혼주 메이크업에 대한 설명으로 가장 알맞은 것은?","신랑·신부의 부모가 대상이며 단아하고 품위 있게 표현한다",[("신부보다 더 화려하고 진하게 표현한다","혼주는 신부보다 돋보이지 않게 단아하게 합니다."),("주름을 강조해 나이 들어 보이게 한다","주름은 자연스럽게 보완합니다."),("한복을 입을 때는 메이크업을 하지 않는다","한복에 어울리는 메이크업을 합니다.")],"혼주 = 신랑·신부 부모, 단아·품위","**혼주**는 신랑·신부의 **부모**입니다. 혼주 메이크업은 피부결과 주름을 자연스럽게 보완하고 한복이나 정장에 어울리는 **단아하고 품위 있는** 색조로 표현합니다.",4,["웨딩 메이크업"])
Q(C,'intermediate',"신랑 메이크업으로 가장 알맞은 것은?","피부 톤을 고르게 하고 눈썹을 정리하는 정도로 자연스럽게 표현한다",[("신부와 똑같이 진한 색조를 쓴다","신랑은 자연스러움이 기본입니다."),("짙은 붉은색 립스틱을 바른다","부자연스럽습니다."),("반짝이는 펄 섀도로 눈을 강조한다","신랑에게는 어울리지 않습니다.")],"신랑 = 톤 정돈·눈썹 정리, 자연스럽게","**신랑 메이크업**은 피부 톤을 고르게 하고 번들거림을 잡으며 **눈썹을 정리**하는 정도로 **자연스럽게** 표현합니다. 립은 혈색만 살짝 더합니다.",3,["웨딩 메이크업"])
Q(C,'basic',"1920년대 서양 메이크업의 특징으로 가장 알맞은 것은?","가늘고 길게 그린 눈썹과 작고 짙은 입술(플래퍼 스타일)",[("굵고 자연스러운 일자 눈썹","1980년대에 유행했습니다."),("인조 속눈썹을 겹쳐 붙인 큰 인형 눈","1960년대의 특징입니다."),("메이크업을 거의 하지 않은 내추럴 스타일","1920년대의 특징이 아닙니다.")],"1920년대 = 가는 눈썹·작고 짙은 입술","1920년대에는 짧은 머리의 **플래퍼** 스타일과 함께 **가늘고 길게 그린 눈썹**, 짙은 눈매, 윗입술을 작고 도톰하게 그린 **짙은 입술**이 유행했습니다.",3,["시대별 메이크업"])
Q(C,'intermediate',"1950년대 서양에서 유행한 메이크업의 특징으로 가장 알맞은 것은?","눈꼬리를 올린 아이라인과 또렷한 붉은 입술로 여성스러움을 강조했다",[("눈썹을 거의 지워 가늘게 그렸다","가는 눈썹은 1920~30년대의 특징입니다."),("메이크업을 하지 않는 자연주의가 주류였다","1970년대 자연주의와 가깝습니다."),("검은 입술과 창백한 얼굴의 펑크 스타일이 주류였다","1970년대 후반 펑크 문화의 특징입니다.")],"1950년대 = 올린 아이라인·붉은 입술","1950년대에는 영화배우들의 영향으로 **눈꼬리를 올린 아이라인**과 **또렷한 붉은 입술**, 정돈된 눈썹으로 여성스러움을 강조한 메이크업이 유행했습니다.",3,["시대별 메이크업"])
Q(C,'intermediate',"트렌드 메이크업을 기획할 때 가장 먼저 해야 할 일로 알맞은 것은?","패션·뷰티 자료를 모아 유행하는 색·질감·이미지를 분석한다",[("작년과 똑같은 메이크업을 그대로 반복한다","트렌드를 반영하지 못합니다."),("작업자가 좋아하는 색만으로 정한다","자료 분석 없이 정하면 트렌드와 멀어집니다."),("제품 가격이 가장 싼 것부터 고른다","가격은 트렌드 분석이 아닙니다.")],"트렌드 메이크업 = 자료 수집 → 분석 → 표현","트렌드 메이크업은 패션쇼·잡지·광고 등 **자료를 수집**해 유행하는 **색·질감·이미지를 분석**한 뒤, 고객과 상황에 맞게 응용해 표현합니다.",3,["트렌드 메이크업"])
Q(C,'advanced',"낮 시간의 면접(취업) 메이크업으로 가장 알맞은 것은?","깨끗한 피부 표현에 차분한 색조로 단정하고 신뢰감 있게 표현한다",[("화려한 펄과 짙은 스모키 아이로 강조한다","파티 메이크업에 가깝습니다."),("무대용 진한 셰이딩을 넣는다","일상 조명에서는 지나치게 진해 보입니다."),("립 없이 아이라인만 굵게 그린다","균형이 맞지 않습니다.")],"면접 = 단정·신뢰감, 차분한 색조","TPO 에 맞춰, **낮의 면접**은 깨끗한 피부 표현과 **차분하고 자연스러운 색조**로 **단정하고 신뢰감 있는** 이미지를 만듭니다. 밤의 파티는 펄과 진한 색조로 화려하게 표현할 수 있습니다.",4,["TPO 메이크업"])
Q(C,'advanced',"스모키 메이크업의 표현 방법으로 가장 알맞은 것은?","어두운 색 섀도를 눈 가장자리에서 바깥쪽으로 경계 없이 번지게 펴 바른다",[("밝은 파스텔 색만 눈두덩에 얇게 바른다","스모키가 아니라 내추럴 메이크업에 가깝습니다."),("아이라인 없이 마스카라만 바른다","스모키 표현이 되지 않습니다."),("눈두덩에 경계선을 뚜렷하게 남긴다","스모키는 경계 없이 그러데이션합니다.")],"스모키 = 어두운 색을 경계 없이 그러데이션","**스모키 메이크업**은 검정·회색·갈색 등 **어두운 색**을 눈 가장자리에서 바깥쪽으로 **경계 없이 번지게** 펴 발라 연기처럼 그윽한 눈매를 만듭니다.",3,["패션 이미지 메이크업"])
Q(C,'basic',"사진·영상 촬영용 메이크업에서 주의할 점으로 가장 알맞은 것은?","조명에 번들거리지 않도록 유분을 잘 잡고 피부 표현을 꼼꼼히 한다",[("조명이 밝으므로 메이크업을 하지 않는다","강한 조명에서는 피부 결점과 혈색 부족이 드러납니다."),("펄을 얼굴 전체에 많이 바른다","조명에 번들거려 보입니다."),("피부 표현을 얇게 하고 유분을 그대로 둔다","번들거림이 드러납니다.")],"촬영 = 번들거림 방지·꼼꼼한 피부 표현","촬영용 메이크업은 강한 조명과 카메라에 결점과 번들거림이 잘 드러나므로 **유분을 잘 잡고** 피부 표현을 **꼼꼼히** 하며, 윤곽을 조금 더 또렷하게 표현합니다.",3,["미디어 메이크업"])
C='character-makeup'
Q(C,'basic',"배우의 머리카락을 감추어 대머리처럼 표현할 때 쓰는 것은?","볼드캡",[("가발 망","가발 망은 가발을 쓰기 전에 머리를 정리하는 데 씁니다."),("더마 왁스","더마 왁스는 상처나 코 모양을 만들 때 씁니다."),("크레이프 울(생사)","수염을 표현하는 재료입니다.")],"대머리 표현 = 볼드캡","**볼드캡**은 머리카락을 덮어 **대머리**처럼 보이게 하는 얇은 캡입니다. 글라잔·라텍스 등으로 만들어 머리에 씌우고, 이마와의 경계를 접착제와 메이크업으로 자연스럽게 감춥니다.",4,["볼드캡"])
Q(C,'intermediate',"노인 캐릭터(노역) 메이크업에서 주름을 표현하는 기본 방법은?","주름이 들어갈 곳은 어두운 색, 주름 사이 튀어나온 곳은 밝은 색으로 표현한다",[("얼굴 전체를 밝은 색 하나로 고르게 칠한다","입체감이 없어 주름이 보이지 않습니다."),("주름이 들어갈 곳에 하이라이트를 준다","들어간 곳은 어둡게 해야 합니다."),("볼에 붉은 블러셔를 진하게 넣는다","젊고 생기 있게 보입니다.")],"주름 = 들어간 곳 어둡게 + 튀어나온 곳 밝게","노역 메이크업은 얼굴 근육을 찡그려 생기는 주름 자리를 찾아 **들어간 곳은 어두운 색(셰이딩)**, 그 옆 **튀어나온 곳은 밝은 색(하이라이트)**으로 표현해 입체적인 주름을 만듭니다.",4,["연령별 캐릭터"])
Q(C,'intermediate',"수염을 표현할 때 쓰는 재료끼리 바르게 짝지은 것은?","크레이프 울과 스피리트 검",[("볼드캡과 라텍스","볼드캡 재료입니다."),("더마 왁스와 인조 피","상처 표현 재료입니다."),("아이패치와 글루","속눈썹 연장 도구입니다.")],"수염 = 크레이프 울 + 스피리트 검","수염은 양모를 꼬아 만든 **크레이프 울**(또는 생사) 같은 수염용 털을 풀어 색을 섞고, 피부에 **스피리트 검**(접착제)을 발라 털이 자라는 방향대로 조금씩 붙여 표현합니다.",4,["수염 표현"])
Q(C,'basic',"상처 메이크업에서 살이 부풀거나 찢어진 모양을 만들 때 주로 쓰는 재료는?","더마 왁스",[("파우더 파운데이션","살의 입체를 만들 수 없습니다."),("마스카라","속눈썹 제품입니다."),("립 글로스","입술에 윤기를 주는 제품입니다.")],"상처 입체 표현 = 더마 왁스","**더마 왁스**는 피부에 붙여 모양을 빚을 수 있는 왁스로, 찢어진 상처나 부은 살을 만들 때 씁니다. 모양을 만든 뒤 파운데이션으로 피부색을 맞추고 인조 피(블러드)로 마무리합니다.",4,["상처 메이크업"])
Q(C,'intermediate',"무대 공연 메이크업이 일상 메이크업과 다른 점으로 가장 알맞은 것은?","먼 객석에서도 보이도록 윤곽과 색을 더 강하고 또렷하게 표현한다",[("관객과 가까우므로 최대한 옅게 한다","무대는 객석과 멀어 옅으면 얼굴이 보이지 않습니다."),("조명이 없으므로 밝은 색만 쓴다","무대는 강한 조명을 씁니다."),("작품 내용과 관계없이 같은 메이크업을 한다","작품과 캐릭터를 분석해 표현합니다.")],"무대 = 먼 거리·강한 조명 → 강하고 또렷하게","무대 공연 메이크업은 객석과의 **거리**와 강한 **조명** 때문에 일상보다 **윤곽과 색을 강하고 또렷하게** 표현합니다. 작품과 캐릭터를 먼저 분석해 디자인합니다.",4,["무대공연 메이크업"])
Q(C,'advanced',"미디어 캐릭터 메이크업을 기획하는 순서로 가장 알맞은 것은?","작품·캐릭터 분석 → 디자인(디자인 맵) → 재료 준비 → 표현",[("재료 준비 → 표현 → 작품 분석 → 디자인","분석 없이 표현하면 캐릭터와 맞지 않습니다."),("표현 → 디자인 → 작품 분석 → 재료 준비","순서가 거꾸로입니다."),("디자인 → 표현 → 재료 준비 → 작품 분석","분석이 가장 먼저입니다.")],"캐릭터 메이크업 = 분석 → 디자인 → 준비 → 표현","캐릭터 메이크업은 대본·작품을 읽고 **캐릭터의 나이·성격·환경을 분석**한 뒤, 디자인을 그리고(디자인 맵), 재료를 준비해 표현합니다. 매체(영화·드라마·광고)의 특성도 함께 고려합니다.",3,["미디어 캐릭터"],lock=True)
Q(C,'advanced',"멍(타박상)을 표현할 때 시간에 따른 색 변화로 가장 알맞은 것은?","처음에는 붉은빛·보랏빛, 시간이 지나면 녹색·노란빛으로 변해 간다",[("처음에는 노란빛, 시간이 지나면 붉은빛으로 변한다","색 변화의 순서가 거꾸로입니다."),("처음부터 끝까지 검은색 하나로 표현한다","실제 멍의 색 변화를 나타내지 못합니다."),("흰색 하이라이트만으로 표현한다","멍의 색을 표현하지 못합니다.")],"멍 색 = 붉음·보라 → 녹색·노랑","멍은 생긴 직후에는 **붉은빛·보랏빛**을 띠고, 시간이 지나 낫기 시작하면 **녹색·노란빛**으로 변합니다. 캐릭터 상황(다친 지 얼마나 되었는지)에 맞춰 색을 고릅니다.",3,["상처 메이크업"])
Q(C,'basic',"캐릭터 메이크업에서 '인조 피(블러드)'의 용도로 가장 알맞은 것은?","상처에서 피가 나는 모습을 표현한다",[("속눈썹을 붙인다","속눈썹 글루의 용도입니다."),("대머리를 표현한다","볼드캡의 용도입니다."),("피부의 유분을 잡는다","파우더의 용도입니다.")],"인조 피 = 피 표현","**인조 피(블러드)**는 상처 메이크업의 마무리 단계에서 **피가 흐르거나 굳은 모습**을 표현할 때 씁니다. 굳은 피는 어둡고 탁하게, 막 흐르는 피는 밝고 윤기 있게 표현합니다.",3,["상처 메이크업"])
